+	if err != nil {
+		return err
+	}
+	manifest.Freshness = freshness
+	manifest.RefreshedAt = opts.Now().UTC()
+	if err := writeWorkspaceManifest(opts.Env, manifest); err != nil {
+		return err
+	}
+	for _, repo := range freshness {
+		fmt.Fprintf(cmd.OutOrStdout(), "%s %s\n", repo.RepoKey, repo.State)
+	}
+	return nil
+}
